    "src/main/java/domain/Parametro.java": "package domain;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Objects;

/**
 * Fila de la tabla ls_parametros (parámetros de negocio de PKG_LIQUIDACION_SINIESTROS).
 * Columnas inferidas por posición del INSERT: codigo, valor_numerico, valor_texto, descripcion.
 */
public record Parametro(String codigo, BigDecimal valorNumerico, String valorTexto, String descripcion) {

    public static final int ESCALA_VALOR_NUMERICO = 4;

    public Parametro {
        Objects.requireNonNull(codigo, "codigo");
        if (valorNumerico != null) {
            valorNumerico = valorNumerico.setScale(ESCALA_VALOR_NUMERICO, RoundingMode.HALF_UP);
        }
    }
}
