    "src/main/java/app/InMemoryParametroRepository.java": "package app;

import domain.Parametro;
import domain.ParametroRepository;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/** Adaptador EN MEMORIA del puerto ParametroRepository, cargado desde input["_tablas"]. */
final class InMemoryParametroRepository implements ParametroRepository {

    private final List<Parametro> filas = new ArrayList<>();

    @Override
    public void insertar(Parametro parametro) {
        filas.add(parametro);
    }

    @Override
    public List<Parametro> listar() {
        return List.copyOf(filas);
    }

    /** Carga las filas iniciales de la tabla ls_parametros (si vienen en _tablas). */
    @SuppressWarnings("unchecked")
    static InMemoryParametroRepository desdeTablas(Map<String, Object> input) {
        InMemoryParametroRepository repo = new InMemoryParametroRepository();
        if (input == null) {
            return repo;
        }
        Object tablas = input.get("_tablas");
        if (!(tablas instanceof Map<?, ?> mapaTablas)) {
            return repo;
        }
        for (Map.Entry<?, ?> e : mapaTablas.entrySet()) {
            if (!"ls_parametros".equalsIgnoreCase(String.valueOf(e.getKey()))) {
                continue;
            }
            if (e.getValue() instanceof List<?> lista) {
                for (Object fila : lista) {
                    if (fila instanceof Map<?, ?> m) {
                        repo.filas.add(aParametro((Map<String, Object>) m));
                    }
                }
            }
        }
        return repo;
    }

    private static Parametro aParametro(Map<String, Object> fila) {
        Object num = columna(fila, "valor_numerico");
        BigDecimal valor = num == null ? null : new BigDecimal(String.valueOf(num));
        Object txt = columna(fila, "valor_texto");
        Object desc = columna(fila, "descripcion");
        return new Parametro(
            String.valueOf(columna(fila, "codigo")),
            valor,
            txt == null ? null : String.valueOf(txt),
            desc == null ? null : String.valueOf(desc));
    }

    private static Object columna(Map<String, Object> fila, String nombre) {
        for (Map.Entry<String, Object> e : fila.entrySet()) {
            if (e.getKey().equalsIgnoreCase(nombre)) {
                return e.getValue();
            }
        }
        return null;
    }
}
